const{chromium}=require('/Users/allanbranch/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');const assert=require('node:assert/strict'),d=require('../docs/finance-dashboard.json');
(async()=>{const b=await chromium.launch({channel:'chrome',headless:true});try{const p=await b.newPage();const errors=[];p.on('pageerror',e=>errors.push(e.message));for(const route of ['','public-safety-preview.html'])for(const width of [320,390,768,1280]){await p.setViewportSize({width,height:1000});await p.goto((process.env.PCARDS_TEST_URL||'http://localhost:4398/')+route);await p.locator('.finance-group').first().waitFor();for(const mode of ['departments','revenues']){await p.locator(`.finance-tabs [data-mode="${mode}"]`).click();const expected=mode==='departments'?d.departments.map(a=>a.id):['millage',...d.revenues.map(a=>a.id)];const ids=await p.locator('.expense-dashboard-card').evaluateAll(es=>es.map(e=>e.dataset.comparisonId));assert.deepEqual([...ids].sort(),expected.sort());assert.equal(new Set(ids).size,ids.length);assert.equal(await p.locator('.finance-group').count(),mode==='departments'?9:7);assert.equal(await p.locator('.finance-add-card').count(),0);assert.equal(await p.getByRole('button',{name:/^Remove /}).count(),0);for(const a of await p.locator('.finance-group-nav a').all()){const href=await a.getAttribute('href');assert.equal(await p.locator(href).count(),1);}await p.locator('.finance-group-nav a').last().click();assert((await p.locator('.finance-group').last().boundingBox()).y>=0);await p.locator('.expense-dashboard-card details').evaluateAll(es=>es.forEach(e=>e.open=true));assert(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),JSON.stringify(await p.evaluate(()=>[...document.querySelectorAll('.expense-dashboard-card *')].filter(e=>e.getBoundingClientRect().right>innerWidth+1).slice(0,10).map(e=>({text:e.textContent.slice(0,50),cls:e.className})))));await p.locator('details').evaluateAll(es=>es.forEach(e=>e.open=false));await p.locator('.finance-group').first().scrollIntoViewIfNeeded();assert.equal(await p.getByText('About these comparisons',{exact:true}).count(),0);assert.equal(await p.locator('.expense-dial').count(),0);const card=p.locator('.expense-dashboard-card').first();await card.getByRole('button',{name:'View yearly breakdown'}).click();assert.equal(await p.getByRole('dialog').locator('tbody tr').count(),mode==='revenues'?d.millage.length:16);await p.keyboard.press('Escape');}console.log('PASS all accounts, unique groups, navigation, dialogs, expanded overflow',route||'home',width);}assert.deepEqual(errors,[]);}finally{await b.close()}})().catch(e=>{console.error(e);process.exit(1)});
